INSERT INTO designs (title, description, image_url, is_active) VALUES
  ('I Scream, You Scream — Ice Cream Day', 'Patriotic ice cream cone with American flag sunglasses — I scream, you scream, we all scream for ice cream. Happy US Ice Cream Day!', '/images/designs/i-scream-you-scream-ice-cream-day.png', true),
  ('Just Here for the Ice Cream', 'Cool ice cream cone with star sunglasses — I am just here for the ice cream, everything else is melting. Happy US Ice Cream Day!', '/images/designs/just-here-for-ice-cream.png', true),
  ('Red, White & Scoops', 'Patriotic sundae bowl with American flag sunglasses — Red, White & Scoops. Freedom is sweet, sprinkles are mandatory.', '/images/designs/red-white-and-scoops.png', true),
  ('CEOs of Chaos — Parents Day', 'Snarky mom with bandana and coffee mug — Happy Parents Day to the real CEOs of Chaos. Fueled by caffeine and denial.', '/images/designs/ceos-of-chaos-parents-day.png', true),
  ('World''s Okayest Parent', 'Raccoon with American flag sunglasses and World''s Okayest Parent mug — Parenting: powered by love, sustained by caffeine, running on 3 hours of sleep.', '/images/designs/worlds-okayest-parent.png', true),
  ('Parenting: Powered by Love — Raccoon', 'Raccoon with American flag glasses holding I Do What I Can mug — Parenting: powered by love, fueled by coffee, & survival mode 24/7. Happy Parents Day!', '/images/designs/parenting-powered-by-love-raccoon.png', true),
  ('Snacks Are Currency — Parents Day', 'Cool cat on couch with snacks — Parenting: where quiet time is a myth and snacks are currency. Don''t judge, I''m doing my best.', '/images/designs/parenting-snacks-are-currency.png', true),
  ('Raising Humans Is Exhausting', 'Snarky chicken with bandana and coffee — Raising humans is exhausting, but so is everything worth doing. Surviving on love & leftover snacks.', '/images/designs/raising-humans-is-exhausting.png', true);
